import React, { useEffect, useState } from 'react';
import './AddAdvertisement.css';

const AddAdvertisement = () => {
  const [ads, setAds] = useState([]);
  const [form, setForm] = useState({ title: '', description: '', imageFile: null, imagePreview: null });
  const [editingId, setEditingId] = useState(null);

  const fetchAds = () => {
    fetch('http://localhost:5000/advertisements')
      .then(res => res.json())
      .then(data => setAds(data))
      .catch(console.error);
  };

  useEffect(() => {
    fetchAds();
  }, []);

  const handleInputChange = e => {
    const { name, value } = e.target;
    setForm(prev => ({ ...prev, [name]: value }));
  };

  const handleImageChange = e => {
    const file = e.target.files[0];
    if (file) {
      setForm(prev => ({ ...prev, imageFile: file }));
      const reader = new FileReader();
      reader.onload = () => setForm(prev => ({ ...prev, imagePreview: reader.result }));
      reader.readAsDataURL(file);
    }
  };

  const resetForm = () => {
    setForm({ title: '', description: '', imageFile: null, imagePreview: null });
    setEditingId(null);
  };

  // Convert image file to base64
// Convert image file to base64 and remove prefix
const toBase64 = file =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.readAsDataURL(file);
    reader.onload = () => {
      // Remove data URL prefix
      const base64 = reader.result.split(',')[1];
      resolve(base64);
    };
    reader.onerror = error => reject(error);
  });


const handleSubmit = async e => {
  e.preventDefault();
  if (!form.title || !form.description || !form.imageFile) {
    alert('Please fill all fields and select image.');
    return;
  }

  try {
    const base64Image = await toBase64(form.imageFile);
    const response = await fetch('http://localhost:5000/advertisements', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        title: form.title,
        description: form.description,
        base64Image,
        fileName: form.imageFile.name,
      }),
    });
    // Handle response...
  } catch (err) {
    alert('Error: ' + err.message);
  }
};


  const handleEdit = id => {
    const ad = ads.find(a => a.id === id);
    if (ad) {
      setForm({ title: ad.title, description: '', imageFile: null, imagePreview: ad.imageUrl });
      setEditingId(id);
    }
  };

  const handleDelete = async id => {
    if(window.confirm('Are you sure to delete this advertisement?')) {
      try {
        const response = await fetch(`http://localhost:5000/advertisements/${id}`, { method: 'DELETE' });
        if (response.ok) fetchAds();
        else alert('Failed to delete');
      } catch (err) {
        alert('Error: ' + err.message);
      }
    }
  };

  return (
    <div className="admin-container">
      <h2>{editingId ? 'Edit Advertisement' : 'Add Advertisement'}</h2>
      <form onSubmit={handleSubmit} className="admin-form">
        <input
          type="text"
          name="title"
          placeholder="Title"
          value={form.title}
          onChange={handleInputChange}
          required
        />
        <textarea
          name="description"
          placeholder="Description"
          value={form.description}
          onChange={handleInputChange}
          required
        />
        <input type="file" accept="image/*" onChange={handleImageChange} />
        {form.imagePreview && <img src={form.imagePreview} alt="preview" className="preview-image" />}
        <button type="submit">{editingId ? 'Update' : 'Add'}</button>
        {editingId && <button type="button" onClick={resetForm}>Cancel</button>}
      </form>

      <h3>Existing Advertisements</h3>
      <div className="ads-list">
        {ads.map(ad => (
          <div key={ad.id} className="ads-list-item">
            <img src={ad.imageUrl} alt={ad.title} />
            <div className="ads-list-info">
              <p>{ad.title}</p>
              <button onClick={() => handleEdit(ad.id)}>Edit</button>
              <button onClick={() => handleDelete(ad.id)}>Delete</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default AddAdvertisement;
